def process_batch(order_data):
    total_revenue = 0.0
    unprocessed_ids = []

    for entry in order_data:
        try:
            revenue = entry['amount'] * entry['quantity']
            total_revenue += revenue
        except (KeyError, TypeError):
            try:
                unprocessed_ids.append(entry['id'])
            except (KeyError, TypeError):
                unprocessed_ids.append(None)

    return total_revenue, unprocessed_ids
